// Complete operating model. Initial data is expressly illustrative and editable.
const money=n=>'₦'+Number(n||0).toLocaleString('en-NG',{maximumFractionDigits:2});
if(!db.completeModules){db.staff=[{id:'STAFF-001',name:'sample client coordinator',venture:'medialy',role:'client care and conversion',supervisor:'medialy ceo',target:20,achieved:8,kpi:'qualified enquiries progressed',salary:80000,salaryStatus:'not paid',commission:10000,commissionStatus:'pending approval',review:'sample review: follow-up evidence needs checking'},{id:'STAFF-002',name:'sample delivery specialist',venture:'bizdoc',role:'document operations',supervisor:'bizdoc ceo',target:12,achieved:5,kpi:'approved service deliveries',salary:90000,salaryStatus:'not paid',commission:7000,commissionStatus:'pending approval',review:''},{id:'STAFF-003',name:'sample systems builder',venture:'subt',role:'software configuration and qa',supervisor:'subt ceo',target:4,achieved:2,kpi:'accepted configurations',salary:120000,salaryStatus:'not paid',commission:12000,commissionStatus:'pending approval',review:''}];db.financialSettings={period:new Date().toISOString().slice(0,7),target:1000000,profitRule:'allocation policy awaiting approval',expenseBasis:'recorded approved expenses'};db.expenses=[{id:uid('expense'),venture:'holding',title:'sample workspace software',amount:15000,status:'approved',at:now(),sample:true}];db.requirementTemplates=[{id:'REQ-NAME',title:'please confirm your business name.',kind:'text',why:'the agreed name is reused across the selected services.',venture:'holding',sensitive:false},{id:'REQ-LOGO',title:'do you already have a logo?',kind:'file',why:'we review existing assets before proposing replacement work.',venture:'medialy',sensitive:false},{id:'REQ-DOCS',title:'can you provide the existing business documents?',kind:'file',why:'the operations team checks what is already available for the agreed scope.',venture:'bizdoc',sensitive:false},{id:'REQ-IDENTITY',title:'can you provide the requested identity evidence?',kind:'file',why:'the team confirms applicability to the purchased service. protected uploads use placeholders in this demo.',venture:'bizdoc',sensitive:true}];db.savedOffers=[{id:'OFFER-001',name:'sample business foundation',industry:'interior design',pitch:'combine the missing essentials into a practical starting scope.',items:db.services.filter(s=>s.id.startsWith('item-')).map(s=>s.id),level:0,status:'draft'}];db.renewals=[];db.assignments=[];db.completeModules=true;save()}
function staffOptions(current=''){return db.staff.filter(s=>scope==='holding'||scope==='medialy'||s.venture===scope).map(s=>`<option value="${s.id}" ${s.id===current?'selected':''}>${E(s.name)} / ${E(s.venture)}</option>`).join('')}
function storeLocalFile(file){return new Promise(async(resolve,reject)=>{try{let id=uid('file'),idb=await filesDB;let tx=idb.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=()=>resolve(id);tx.onerror=()=>reject(tx.error)}catch(e){reject(e)}})}
function clientUrgency(l){let escalations=(db.escalations||[]).filter(e=>e.clientId===l.id&&e.status!=='resolved'),overdue=l.due&&new Date(l.due)<new Date(),silent=l.paid&&Date.now()-new Date(l.updates[0]?.at||l.payment?.at||l.created)>48*3600000;return {rank:escalations.some(e=>e.priority==='urgent')?4:overdue?3:silent?2:escalations.length?1:0,reason:escalations.some(e=>e.priority==='urgent')?'urgent escalation':overdue?'next action overdue':silent?'48-hour update due':escalations.length?'open escalation':'on track'}}
function compactLeadList(ls){return `<div class="clientcards">${ls.map(l=>{let u=clientUrgency(l);return `<article class="clientcard rank${u.rank}"><div class="clientcard-top"><span class="small">${E(l.id)}</span>${stageTag(l.stage)}</div><h2>${E(l.name)}</h2><p class="small">${E(l.source)} · ${E(l.venture)}</p><div class="clientcard-action"><span>${u.rank?'!':'✓'} ${u.reason}</span><p>${E(l.next||'review the enquiry')}</p><small>${l.due?displayDate(l.due):'set a follow-up date'}</small></div><div class="actions">${button('open client workspace →','lead/'+l.id)}${button('client view','client/'+l.id+'/reference','secondary mini')}</div></article>`}).join('')||'<div class="empty">no matching client records.</div>'}</div>`}
crm=function(){if(route[1]==='new')return newLead();let ls=scopedLeads().filter(l=>!query||(l.name+' '+l.contact+' '+l.id).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>clientUrgency(b).rank-clientUrgency(a).rank);return title('one client record / the full journey','clients, with a clear next action.','urgent issues rise to the top. answers, scope, payments, work and follow-ups stay in the same record.',button('+ capture enquiry','crm/new'))+`<div class="crm-controls"><input aria-label="search client workspace" placeholder="search business, reference or contact" value="${E(query)}" oninput="query=this.value;document.getElementById('clientresults').innerHTML=compactLeadList(scopedLeads().filter(l=>!query||(l.name+' '+l.contact+' '+l.id).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>clientUrgency(b).rank-clientUrgency(a).rank))"><span class="small">${ls.length} records · urgency sorted</span></div><div id="clientresults">${compactLeadList(ls)}</div>`}
const workspaceTabs=[['overview','overview'],['discovery','answers'],['proposal','proposal'],['roadmap','roadmap'],['payment','payment'],['requirements','requirements'],['delivery','work & delivery'],['updates','updates & support'],['renewals','renewals']];
leadView=function(){let l=lead(route[1]);if(!l)return notFound();if(!inScope(l))return note('this record is outside the selected workspace preview.');let tab=route[2]||'overview',u=clientUrgency(l);return title(E(l.id),E(l.name),`${E(l.source)} · ${E(l.venture)} · ${u.reason}`,button('open client journey ↗','client/'+l.id+'/reference','secondary'))+`<div class="client-summary"><span>${stageTag(l.stage)}</span><span>next: ${E(l.next||'review enquiry')}</span><span>due: ${displayDate(l.due)}</span></div><div class="tabs client-worktabs">${workspaceTabs.map(([key,t])=>`<button class="${key===tab?'active':''}" onclick="go('lead/${l.id}/${key}')">${t}</button>`).join('')}</div>`+(tab==='overview'?clientOverview(l):tab==='proposal'?proposalStudio(l):tab==='roadmap'?roadmapStudio(l):tab==='payment'?paymentStudio(l):tab==='requirements'?requirementsStudio(l):tab==='delivery'?deliveryEditor(l):tab==='updates'?supportStudio(l):tab==='renewals'?renewalStudio(l):leadPanel(l,tab))}
function clientOverview(l){return `<div class="two"><section class="card"><h2>responsibility & next action</h2><form onsubmit="updateLead(event,'${l.id}')"><label>responsible venture</label><select name="venture"><option>holding</option>${db.ventures.map(v=>`<option ${l.venture===v.name?'selected':''}>${E(v.name)}</option>`).join('')}</select><label>next action</label><textarea name="next" required>${E(l.next)}</textarea><label>due date</label><input type="datetime-local" name="due" value="${E(l.due)}"><div class="actions"><button>save next action</button></div></form><div class="actions">${button('open client answers →','lead/'+l.id+'/discovery','secondary')}${button('raise escalation','lead/'+l.id+'/updates','ghost')}</div></section><section class="card"><h2>one continuous history</h2>${l.events.slice(0,20).map(e=>`<div class="statusline"><span class="small">${displayDate(e.at)}</span><p>${E(e.text)}</p></div>`).join('')||'<p>client actions will be recorded here.</p>'}</section></div>`}
function proposalStudio(l){let p=l.proposalDraft||{understood:l.answers.offer||l.answers.activity||l.name,priority:l.answers.goal||'confirm the immediate business priority',recommendation:l.proposal||l.proposalVersion?.text||'',next:'review the roadmap and choose the missing essentials'};return `<div class="proposal-studio"><form class="card" onsubmit="saveStructuredProposal(event,'${l.id}')"><div class="eyebrow">edit / concise recommendation</div><h2>say the useful part clearly.</h2><label>what we understood</label><textarea name="understood" maxlength="240" oninput="liveProposalPreview(this.form)" required>${E(p.understood)}</textarea><label>what matters first</label><textarea name="priority" maxlength="180" oninput="liveProposalPreview(this.form)" required>${E(p.priority)}</textarea><label>what we recommend and why</label><textarea name="recommendation" maxlength="500" oninput="liveProposalPreview(this.form)" required>${E(p.recommendation)}</textarea><label>next action</label><input name="next" maxlength="160" value="${E(p.next)}" oninput="liveProposalPreview(this.form)" required><div class="actions"><button>save draft</button><button type="button" class="secondary" onclick="publishStructuredProposal('${l.id}')">publish saved version</button></div><p class="small">character limits encourage concise copy. publishing freezes a version; draft changes do not alter the client’s published view.</p></form><section class="proposal-preview-wrap"><div class="eyebrow">live client preview</div><article class="proposal-preview" id="proposal-live"><span class="small">hamzury / ${E(l.id)}</span><h2>your next step.</h2>${proposalPreviewBody(p)}</article>${l.proposalVersion?`<div class="linkbox">${E(link('client/'+l.id+'/proposal'))}</div><span class="small">published version ${l.proposalVersion.version||1} · ${displayDate(l.proposalVersion.at)}</span>`:''}</section></div>`}
function proposalPreviewBody(p){return `<p>${E(p.understood)}</p><h3>your first priority</h3><p>${E(p.priority)}</p><p>${E(p.recommendation)}</p><div class="flow-next"><span>your next action</span><strong>${E(p.next)}</strong></div><span class="previewbutton">open my roadmap →</span>`}
function liveProposalPreview(form){let p=Object.fromEntries(new FormData(form));let el=document.getElementById('proposal-live');el.innerHTML='<span class="small">hamzury / draft preview</span><h2>your next step.</h2>'+proposalPreviewBody(p)}
function saveStructuredProposal(e,id){e.preventDefault();let l=lead(id);l.proposalDraft=Object.fromEntries(new FormData(e.target));l.proposal=l.proposalDraft.recommendation;event(l,'structured proposal draft saved');toast('draft saved. publish when ready.')}
function publishStructuredProposal(id){let l=lead(id);if(!l.proposalDraft){toast('save the proposal draft first');return}l.proposalVersion={...structuredClone(l.proposalDraft),text:[l.proposalDraft.understood,l.proposalDraft.priority,l.proposalDraft.recommendation,l.proposalDraft.next].join('\n\n'),at:now(),version:(l.proposalVersion?.version||0)+1};l.stage='proposal';event(l,'proposal published, version '+l.proposalVersion.version);render()}
function roadmapStudio(l){return `<section class="card"><div class="sectionhead"><div><h2>curate from the catalogue.</h2><p>select the services or add a saved offer. published prices and scope are preserved as a snapshot.</p></div>${button('create catalogue item +','catalogue/edit/new','secondary')}</div><form onsubmit="saveClientRoadmap(event,'${l.id}')"><label>add a saved offer to this draft</label><select aria-label="saved offer" onchange="if(this.value)addOfferToClient('${l.id}',this.value)"><option value="">choose a reusable offer</option>${(db.savedOffers||[]).map(o=>`<option value="${o.id}">${E(o.name)}</option>`).join('')}</select>${['minimum','standard','premium','scale & growth'].map((name,n)=>`<details ${n===0?'open':''}><summary>${name}</summary>${db.services.filter(s=>s.level===n).map(s=>`<div class="checkrow"><input id="rs-${s.id}" name="service" type="checkbox" value="${s.id}" ${l.selected.includes(s.id)?'checked':''}><label for="rs-${s.id}"><span class="small">${E(s.code||s.id)} · ${E(s.v)}</span><br><b>${E(s.title)}</b><br><span class="small">${s.price!==''?money(s.price):'price to confirm'} · ${s.days?s.days+' working days':'timing to confirm'}</span></label></div>`).join('')}</details>`).join('')}<div class="actions"><button>save draft</button><button type="button" class="secondary" onclick="publishRoadmapFor('${l.id}')">publish saved roadmap</button></div></form>${l.roadmapVersion?`<div class="linkbox">${E(link('client/'+l.id+'/roadmap'))}</div>`:''}</section>`}
function saveClientRoadmap(e,id){saveRoadmap(e,id)}function addOfferToClient(id,oid){let l=lead(id),o=db.savedOffers.find(o=>o.id===oid);l.selected=[...new Set([...l.selected,...o.items])];event(l,'saved offer added to roadmap draft: '+o.name);render()}
function paymentStudio(l){let receipts=l.receipts||[],quote=l.quote;return `<div class="two"><section class="card"><h2>quotation & order record</h2><p>selected scope: ${(l.clientSelected||l.selected).length} services.</p>${quote?`<div class="notice"><b>${E(quote.id)}</b><br>total: ${money(quote.total)} · ${E(quote.status)}<br>${E(quote.terms)}</div>`:'<p>no formal quotation has been recorded.</p>'}<form onsubmit="prepareQuote(event,'${l.id}')"><label>agreed scope, revisions and external fees</label><textarea name="terms" required>${E(quote?.terms||'confirm deliverables, revision limits, delivery basis and any external fees before acceptance.')}</textarea><label>client acceptance record</label><select name="status"><option value="draft">draft / awaiting client acceptance</option><option value="accepted" ${quote?.status==='accepted'?'selected':''}>accepted, evidence recorded</option></select><label>acceptance evidence reference</label><input name="evidence" value="${E(quote?.evidence||'')}" placeholder="sample signed scope or acceptance message"><div class="actions"><button>save quotation snapshot</button></div></form>${note('catalogue prices must be entered for every selected item before a priced quotation can be recorded. no real payment is collected by this interface.')}</section><section class="card"><h2>receipts & finance verification</h2><form onsubmit="addReceipt(event,'${l.id}')"><label>amount submitted (₦)</label><input type="number" name="amount" min="1" step="0.01" required><label>transaction reference</label><input name="ref" required><label>receipt / evidence (sample file, up to 2 mb)</label><input name="receipt" type="file" required><label>submitted by</label><select name="submittedBy"><option>staff on behalf of client</option><option>client</option></select><div class="actions"><button>record receipt for review</button></div></form>${receipts.map(r=>`<article class="receiptrow"><b>${money(r.amount)}</b> ${stageTag(r.status==='verified'?'active':'payment')}<p class="small">${E(r.ref)} · ${E(r.submittedBy)}<br>${displayDate(r.at)}</p><button class="secondary mini" onclick="downloadFile('${r.fileId}')">view receipt</button>${r.status!=='verified'?`<button class="mini" onclick="verifyReceipt('${l.id}','${r.id}')">verify & activate agreed scope</button>`:`<p class="small">verified: ${displayDate(r.verifiedAt)}</p>`}</article>`).join('')}<div class="note">a submitted receipt does not mark an order paid. verification requires an accepted quotation, the verified reference and the agreed funded scope.</div></section></div>`}
function prepareQuote(e,id){e.preventDefault();let l=lead(id),sv=(l.roadmapVersion?.services||[]).filter(s=>(l.clientSelected||l.selected).includes(s.id));if(!sv.length||sv.some(s=>s.price==='')){toast('publish priced services and confirm the client selection first');return}let d=Object.fromEntries(new FormData(e.target));if(d.status==='accepted'&&!d.evidence.trim()){toast('record the client acceptance evidence');return}l.quote={...d,id:uid('QUOTE'),services:structuredClone(sv),total:sv.reduce((n,s)=>n+Number(s.price),0),at:now()};event(l,'quotation snapshot recorded: '+d.status);render()}
async function addReceipt(e,id){e.preventDefault();let d=new FormData(e.target),f=d.get('receipt'),l=lead(id);if(!f?.size||f.size>2*1024*1024){toast('choose a test receipt smaller than 2 mb');return}try{let fid=await storeLocalFile(f);l.receipts=l.receipts||[];l.receipts.push({id:uid('receipt'),amount:Number(d.get('amount')),ref:d.get('ref'),submittedBy:d.get('submittedBy'),fileId:fid,status:'submitted',at:now()});l.receiptSubmitted=true;event(l,'payment receipt submitted for verification');render()}catch{toast('the test receipt could not be stored')}}
function verifyReceipt(id,rid){let l=lead(id),r=l.receipts.find(r=>r.id===rid);if(!l.quote||l.quote.status!=='accepted'){toast('record an accepted quotation first');return}if(r.status==='verified')return;let verified=(l.receipts||[]).filter(r=>r.status==='verified').reduce((n,r)=>n+r.amount,0)+r.amount;r.status='verified';r.verifiedAt=now();if(verified<l.quote.total){event(l,'partial receipt verified; remaining balance '+money(l.quote.total-verified));render();toast('partial payment recorded; activation awaits the funded scope');return}l.payment={amount:verified,ref:r.ref,at:now(),simulation:true};l.paid=true;l.activeSelection=l.quote.services.map(s=>s.id);l.quote.services.forEach(s=>{if(!l.work.some(w=>w.serviceId===s.id))l.work.push({id:uid('work'),serviceId:s.id,venture:s.v,title:s.title,status:'ready',owner:'venture operations lead',due:'',standard:s.deliver,evidence:''})});l.stage='onboarding';l.next='complete the purchased-service requirements';event(l,'receipt verified and funded scope activated');prepareRequirementJourney(l);render()}
function requirementsStudio(l){if(!l.paid)return note('requirements open after the agreed scope is funded, so the questions match the purchased services.');prepareRequirementJourney(l);return `<div class="two"><section class="card"><h2>requirements for this scope</h2>${l.requirements.map(r=>`<article class="receiptrow"><b>${E(r.title)}</b><p>${E(r.why)}</p><p class="small">${E(r.status)} · ${E(r.venture)}${r.sensitive?' · protected sample':''}</p><p>${E(r.answer||'')}</p>${(r.fileIds||[]).map(f=>`<button class="secondary mini" onclick="downloadFile('${f}')">open sample file</button>`).join('')}<div class="actions"><button class="secondary mini" onclick="reviewRequirement('${l.id}','${r.id}','accepted')">accept</button><button class="secondary mini" onclick="reviewRequirement('${l.id}','${r.id}','needed')">request again</button></div></article>`).join('')}${button('preview one-question journey','client/'+l.id+'/requirements','secondary')}</section><section class="card"><h2>add the next relevant question</h2><label>reusable template</label><select onchange="if(this.value)addRequirementTemplate('${l.id}',this.value)"><option value="">choose a requirement</option>${db.requirementTemplates.map(r=>`<option value="${r.id}">${E(r.title)}</option>`).join('')}</select><form onsubmit="addCustomRequirement(event,'${l.id}')"><label>question</label><input name="title" required><label>why we need this</label><textarea name="why" required></textarea><label>response</label><select name="kind"><option value="text">text answer</option><option value="file">file or availability</option></select><label>responsible venture</label><select name="venture"><option>holding</option>${db.ventures.map(v=>`<option>${E(v.name)}</option>`).join('')}</select><label class="checkrow"><input type="checkbox" name="sensitive">protected identity / signature (sample only)</label><label class="checkrow"><input type="checkbox" name="reuse">also save as a reusable template</label><div class="actions"><button>add question</button></div></form></section></div>`}
function reviewRequirement(id,rid,status){let l=lead(id),r=l.requirements.find(r=>r.id===rid);if(status==='accepted'&&!['submitted','accepted'].includes(r.status)){toast('a response must be submitted before acceptance');return}r.status=status;event(l,'requirement '+status+': '+r.title);render()}
function addRequirementTemplate(id,rid){let l=lead(id),r=db.requirementTemplates.find(r=>r.id===rid);l.requirements.push({...structuredClone(r),id:uid('req'),status:'needed',answer:'',fileIds:[]});event(l,'requirement template added');render()}
function addCustomRequirement(e,id){e.preventDefault();let d=Object.fromEntries(new FormData(e.target)),l=lead(id),r={title:d.title,why:d.why,kind:d.kind,venture:d.venture,sensitive:!!d.sensitive};if(d.reuse)db.requirementTemplates.push({...r,id:uid('template')});l.requirements.push({...r,id:uid('req'),status:'needed',answer:'',fileIds:[]});event(l,'custom requirement added');render()}
function supportStudio(l){let es=(db.escalations||[]).filter(e=>e.clientId===l.id);return leadPanel(l,'updates')+`<section class="card" style="margin-top:22px"><h2>support & escalations / in this journey</h2><form onsubmit="raiseClientEscalation(event,'${l.id}')"><label>blocker, complaint or feedback</label><textarea name="issue" required></textarea><div class="formgrid"><div><label>priority</label><select name="priority"><option>normal</option><option>urgent</option></select></div><div><label>responsible owner</label><select name="owner">${staffOptions()}</select></div><div><label>response deadline</label><input type="datetime-local" name="due" required></div></div><div class="actions"><button>record escalation</button></div></form>${es.map(e=>`<div class="receiptrow"><b>${E(e.priority)} · ${E(e.status)}</b><p>${E(e.issue||e.summary||'')}</p><p class="small">${E(db.staff.find(s=>s.id===e.owner)?.name||e.owner)} · ${displayDate(e.due)}</p>${e.status!=='resolved'?`<button class="secondary mini" onclick="resolveClientEscalation('${l.id}','${e.id}')">record resolution</button>`:`<p>${E(e.resolution||'resolved')}</p>`}</div>`).join('')}</section>`}
function raiseClientEscalation(e,id){e.preventDefault();let l=lead(id),d=Object.fromEntries(new FormData(e.target));db.escalations=db.escalations||[];db.escalations.unshift({...d,id:uid('escalation'),clientId:id,venture:l.venture,status:'open',at:now()});event(l,'support escalation recorded: '+d.priority);render()}
function resolveClientEscalation(id,eid){let resolution=prompt('what was resolved, and what happens next?');if(!resolution?.trim())return;let e=db.escalations.find(e=>e.id===eid);e.status='resolved';e.resolution=resolution;e.resolvedAt=now();event(lead(id),'escalation resolved: '+resolution);render()}
function renewalStudio(l){return `<section class="card"><h2>renewals & future follow-up</h2><p>record the date while delivering the work. reminders are reviewed here; this preview does not send messages.</p><form onsubmit="addRenewal(event,'${l.id}')"><div class="formgrid"><div><label>service / reason</label><input name="title" required></div><div><label>renewal date</label><input type="date" name="date" required></div><div><label>remind this many days before</label><input type="number" name="leadDays" value="30" min="0" required></div><div><label>owner</label><select name="owner">${staffOptions()}</select></div></div><div class="actions"><button>save follow-up date</button></div></form>${db.renewals.filter(r=>r.clientId===l.id).map(r=>`<div class="receiptrow"><b>${E(r.title)}</b><p>due ${E(r.date)} · review from ${E(renewalReminderDate(r))}</p><span class="small">${E(r.status)} · ${E(db.staff.find(s=>s.id===r.owner)?.name||r.owner)}</span><div class="actions"><button class="secondary mini" onclick="markRenewal('${r.id}')">record reminder sent manually</button></div></div>`).join('')}</section>`}
function renewalReminderDate(r){return new Date(new Date(r.date+'T12:00:00Z').getTime()-Number(r.leadDays)*86400000).toISOString().slice(0,10)}
function addRenewal(e,id){e.preventDefault();db.renewals.push({...Object.fromEntries(new FormData(e.target)),id:uid('renewal'),clientId:id,status:'planned',at:now()});event(lead(id),'renewal date recorded');render()}
function markRenewal(id){let r=db.renewals.find(r=>r.id===id);r.status='sent manually';r.sentAt=now();event(lead(r.clientId),'manual reminder recorded: '+r.title);render()}
const originalCatalogue=catalogue,originalServiceEditor=serviceEditor;
catalogue=function(){if(route[1]==='edit')return serviceEditor(route[2]);return title('service shelves','the right combination, for the right stage.','industry → package stage → venture → service. prices and examples remain editable.',button('+ add service','catalogue/edit/new'))+`<div class="actions">${button('reusable offers','offers','secondary')}</div>${[...new Set(db.services.map(s=>s.industry||'general business'))].map(ind=>`<section class="card" style="margin-top:20px"><div class="eyebrow">industry shelf</div><h2>${E(ind)}</h2>${['minimum','standard','premium','scale & growth'].map((stage,i)=>`<details ${i===0?'open':''}><summary>${stage}</summary>${db.ventures.map(v=>{let services=db.services.filter(s=>(s.industry||'general business')===ind&&s.level===i&&s.v===v.name);return services.length?`<h3>${E(v.name)}</h3>${services.map(s=>`<div class="receiptrow"><span class="small">${E(s.code||s.id)}</span><h3>${E(s.title)}</h3><p>${E(s.scope)}</p><p class="small">${s.price!==''?money(s.price):'price to confirm'} · ${s.days||'—'} working days</p><details><summary>delivery & sales guide</summary><p>${E(s.deliver)}</p><p>requirements: ${E(s.req)}</p><p>${E(s.salesGuide||'explain the gap this item solves; check what the client already has before recommending it.')}</p></details>${button('edit item','catalogue/edit/'+s.id,'secondary mini')}</div>`).join('')}`:''}).join('')}</details>`).join('')}</section>`).join('')}`}
serviceEditor=function(id){let s=db.services.find(s=>s.id===id)||{};return originalServiceEditor(id).replace('<div class="actions"><button>save service draft',`<label>internal service code</label><input name="code" value="${E(s.code||s.id||'')}" required><label>internal sales guidance</label><textarea name="salesGuide">${E(s.salesGuide||'')}</textarea><label>prerequisite service ids (comma separated)</label><input name="dependsText" value="${E((s.dependencies||[]).join(', '))}"><div class="actions"><button>save service draft`)};
const originalSaveService=saveService;
saveService=function(e,id){let d=new FormData(e.target),deps=String(d.get('dependsText')||'').split(',').map(s=>s.trim()).filter(Boolean);if(deps.some(x=>x===id||!db.services.some(s=>s.id===x))){e.preventDefault();toast('prerequisites must be other existing service ids');return}let graph=new Map(db.services.map(s=>[s.id,s.id===id?deps:s.dependencies||[]]));function cycle(x,path=new Set()){if(path.has(x))return true;let next=new Set(path).add(x);return(graph.get(x)||[]).some(y=>cycle(y,next))}if(cycle(id)){e.preventDefault();toast('prerequisites cannot form a circular dependency');return}originalSaveService(e,id);let s=db.services.find(s=>s.id===id)||db.services.at(-1);s.dependencies=deps;save()};
function offersView(){return title('reusable offers','combine services into a clear outcome.','offers curate catalogue items. clients still choose their missing essentials.')+`<div class="two"><form class="card" onsubmit="saveOffer(event)"><label>offer name</label><input name="name" required><label>industry</label><input name="industry" required><label>what this combination helps solve</label><textarea name="pitch" required></textarea><label>package stage</label><select name="level">${['minimum','standard','premium','scale & growth'].map((t,i)=>`<option value="${i}">${t}</option>`).join('')}</select>${db.services.map(s=>`<label class="checkrow"><input type="checkbox" name="items" value="${s.id}"><span>${E(s.code||s.id)} · ${E(s.title)} / ${E(s.v)}</span></label>`).join('')}<div class="actions"><button>save reusable offer</button></div></form><section>${db.savedOffers.map(o=>`<article class="card" style="margin-bottom:16px"><span class="small">${E(o.id)} · ${E(o.industry)}</span><h2>${E(o.name)}</h2><p>${E(o.pitch)}</p>${o.items.map(id=>`<p class="small">✓ ${E(db.services.find(s=>s.id===id)?.title||id)}</p>`).join('')}</article>`).join('')}</section></div>`}
function saveOffer(e){e.preventDefault();let f=new FormData(e.target),items=f.getAll('items');if(!items.length){toast('choose at least one service');return}db.savedOffers.push({...Object.fromEntries(f),items,level:Number(f.get('level')),id:uid('offer'),status:'draft'});save();render();toast('offer saved for roadmap curation')}
function financeNumbers(){let p=db.financialSettings.period,ls=scopedLeads(),receipts=ls.flatMap(l=>(l.receipts||[]).filter(r=>r.status==='verified'&&(r.verifiedAt||r.at).slice(0,7)===p)),received=receipts.reduce((n,r)=>n+Number(r.amount),0),expenses=db.expenses.filter(e=>e.status==='approved'&&e.at.slice(0,7)===p&&(scope==='holding'||e.venture===scope)).reduce((n,e)=>n+Number(e.amount),0),booked=ls.filter(l=>l.quote?.status==='accepted'&&l.quote.at.slice(0,7)===p).reduce((n,l)=>n+l.quote.total,0);return {received,expenses,booked,gap:Math.max(0,Number(db.financialSettings.target)-received)}}
function financeView(){let f=financeNumbers(),target=Number(db.financialSettings.target);return title('finance / sample ledger','know the gap before it grows.','verified receipts, accepted quotations and approved expenses are separate measures.')+`<div class="grid four">${[[money(f.received),'verified receipts'],[money(f.booked),'accepted quotations'],[money(f.expenses),'approved expenses'],[money(f.gap),'gap to receipt target']].map(([a,b])=>`<article class="card"><span class="small">${b}</span><div class="metric finance-metric">${a}</div></article>`).join('')}</div><section class="card" style="margin-top:20px"><label>receipt target progress · ${target?Math.round(f.received/target*100):0}%</label><progress max="${target||1}" value="${f.received}"></progress><p class="small">cash received less approved recorded expenses: ${money(f.received-f.expenses)}. this is not a profit calculation. ${E(db.financialSettings.profitRule)}.</p></section><div class="two"><form class="card" onsubmit="saveFinanceSettings(event)"><h2>reporting period & target</h2><label>month</label><input type="month" name="period" value="${E(db.financialSettings.period)}" required><label>receipt target (₦)</label><input type="number" min="0" name="target" value="${target}" required><label>allocation / approval policy</label><textarea name="profitRule" required>${E(db.financialSettings.profitRule)}</textarea><div class="actions"><button>save reporting settings</button></div></form><form class="card" onsubmit="saveExpense(event)"><h2>record an expense</h2><label>description</label><input name="title" required><label>amount (₦)</label><input type="number" name="amount" min="1" step="0.01" required><label>venture</label><select name="venture"><option>holding</option>${db.ventures.map(v=>`<option>${E(v.name)}</option>`).join('')}</select><label>approval status</label><select name="status"><option>pending review</option><option>approved</option></select><label>approval reference / note</label><input name="reference" required><div class="actions"><button>record sample expense</button></div></form></div><section class="card"><h2>expense register</h2>${db.expenses.filter(e=>scope==='holding'||e.venture===scope).map(e=>`<div class="row"><div><b>${E(e.title)}</b><p class="small">${E(e.venture)} · ${E(e.status)} · ${E(e.reference||'sample record')}</p></div><strong>${money(e.amount)}</strong></div>`).join('')}</section>`}
function saveFinanceSettings(e){e.preventDefault();Object.assign(db.financialSettings,Object.fromEntries(new FormData(e.target)));save();render()}
function saveExpense(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));db.expenses.unshift({...d,amount:Number(d.amount),id:uid('expense'),at:now()});save();render()}
function staffView(){let s=db.staff.find(s=>s.id===route[1]);if(s&&(scope==='holding'||s.venture===scope)){return title('staff profile',E(s.name),E(s.venture)+' · '+E(s.role))+`<form class="card" onsubmit="saveStaffReview(event,'${s.id}')"><div class="formgrid">${[['name','name'],['role','role'],['supervisor','supervisor'],['kpi','kpi / measure'],['target','target'],['achieved','achieved'],['salary','salary amount'],['commission','commission amount']].map(([k,t])=>`<div><label>${t}</label><input name="${k}" ${['target','achieved','salary','commission'].includes(k)?'type="number" min="0"':'type="text"'} value="${E(s[k])}" required></div>`).join('')}<div><label>salary record</label><select name="salaryStatus">${['not paid','approved','paid'].map(x=>`<option ${s.salaryStatus===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label>commission record</label><select name="commissionStatus">${['pending approval','approved','paid'].map(x=>`<option ${s.commissionStatus===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="full"><label>payment reference and period (required when marking paid)</label><input name="payReference" value="${E(s.payReference||'')}"></div><div class="full"><label>review evidence / coaching / next target</label><textarea name="review">${E(s.review)}</textarea></div></div><div class="actions"><button>save staff review</button></div><p class="small">these are administrative records. no salary or commission transfer is initiated.</p></form>`}return title('people / performance','clear targets. supported delivery.','sample profiles connect ownership, review and administrative pay records.',button('start an onboarding journey','people','secondary'))+`<details class="card" style="margin-bottom:20px"><summary>add a staff profile</summary><form onsubmit="createStaffProfile(event)"><label>staff name (sample)</label><input name="name" required><label>venture</label><select name="venture">${db.ventures.filter(v=>scope==='holding'||v.name===scope).map(v=>`<option>${E(v.name)}</option>`).join('')}</select><label>role</label><input name="role" required><label>supervisor</label><input name="supervisor" required><label>first kpi / measure</label><input name="kpi" required><label>target</label><input type="number" min="1" name="target" required><div class="actions"><button>save profile</button></div><p class="small">creates an administrative profile. account invitations require the live identity system.</p></form></details><div class="clientcards">${db.staff.filter(s=>scope==='holding'||s.venture===scope).map(s=>`<article class="card"><span class="small">${E(s.venture)}</span><h2>${E(s.name)}</h2><p>${E(s.role)}</p><p class="small">${E(s.kpi)}: ${s.achieved} / ${s.target}</p><progress max="${s.target||1}" value="${s.achieved}"></progress><p class="small">salary: ${E(s.salaryStatus)} · commission: ${E(s.commissionStatus)}</p>${button('open profile','staff/'+s.id,'secondary')}</article>`).join('')}</div>`}
function saveStaffReview(e,id){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if((d.salaryStatus==='paid'||d.commissionStatus==='paid')&&!d.payReference.trim()){toast('record the payment reference and period first');return}let s=db.staff.find(s=>s.id===id);Object.assign(s,d);['target','achieved','salary','commission'].forEach(k=>s[k]=Number(s[k]));s.reviewedAt=now();save();toast('staff review saved');render()}
function taskView(){let work=scopedLeads().flatMap(l=>l.work.filter(w=>scope==='holding'||w.venture===scope).map(w=>({l,w})));return title('task relationship management','every task has an owner and a standard.','client work stays attached to its source record. assignments include evidence and a reviewer.')+`<div class="two"><section><h2>client delivery assignments</h2>${work.map(({l,w})=>`<article class="card" style="margin-bottom:16px"><span class="small">${E(l.id)} · ${E(w.venture)}</span><h3>${E(w.title)}</h3><p>${E(w.status)} · ${E(w.owner||'owner needed')}</p><p class="small">${w.due?displayDate(w.due):'set a delivery date'}<br>${E(w.standard||'confirm acceptance standard')}</p>${button('open work & upload delivery','lead/'+l.id+'/delivery','secondary')}</article>`).join('')||note('paid client work will appear here.')}</section><section><form class="card" onsubmit="saveAssignment(event)"><h2>create an internal assignment</h2><label>task / daily result</label><input name="title" required><label>owner</label><select name="owner">${staffOptions()}</select><label>reviewer</label><select name="reviewer">${staffOptions()}</select><label>deadline</label><input type="datetime-local" name="due" required><label>acceptance standard</label><textarea name="standard" required></textarea><div class="actions"><button>assign task</button></div></form>${db.assignments.filter(a=>scope==='holding'||db.staff.find(s=>s.id===a.owner)?.venture===scope).map(a=>`<form class="card" style="margin-top:16px" onsubmit="reviewAssignment(event,'${a.id}')"><h3>${E(a.title)}</h3><p class="small">${E(db.staff.find(s=>s.id===a.owner)?.name)} → reviewer ${E(db.staff.find(s=>s.id===a.reviewer)?.name)}<br>${displayDate(a.due)}</p><p>${E(a.standard)}</p><label>status</label><select name="status">${['assigned','in progress','blocked','under review','approved'].map(x=>`<option ${a.status===x?'selected':''}>${x}</option>`).join('')}</select><label>evidence / review note</label><textarea name="evidence">${E(a.evidence||'')}</textarea><div class="actions"><button class="secondary">save task update</button></div></form>`).join('')}</section></div>`}
function saveAssignment(e){e.preventDefault();db.assignments.unshift({...Object.fromEntries(new FormData(e.target)),id:uid('task'),status:'assigned',at:now()});save();render()}
function reviewAssignment(e,id){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(['under review','approved'].includes(d.status)&&!d.evidence.trim()){toast('add evidence before review or approval');return}Object.assign(db.assignments.find(a=>a.id===id),d);save();render()}
function systemStatus(){return title('system readiness','a complete preview, with clear activation gates.','this workspace uses sample records stored in this browser. it is not yet a shared production crm.')+`<section class="card"><h2>ready to explore</h2><p>discovery, reference cards, proposals, catalogue curation, selection, sample payment verification, requirements, delivery, client updates, escalation, renewals, staff profiles and finance records.</p><h2>needed before real client operations</h2><p>shared database and secure file storage; server-enforced staff and client roles; verified payment provider; controlled email / whatsapp delivery; privacy and retention rules; production backups and audit records.</p><p>reference numbers identify records; they must not become passwords. the workspace selector previews roles and does not grant authenticated access.</p><div class="actions"><button onclick="exportOperatingData()">export sample records</button></div><p class="small">export excludes uploaded file contents. keep exports private.</p></section>`}
function exportOperatingData(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.download='hamzury-sample-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
paths.splice(0,paths.length,...[['workspace','overview'],['crm','client crm & actions'],['work','tasks & delivery'],['finance','finance & targets'],['staff','staff performance'],['venture','venture work'],['forms','discovery studio'],['catalogue','service catalogue'],['offers','reusable offers'],['people','people & onboarding'],['resources-admin','documents & access'],['content','content studio'],['system','system readiness'],['home','holding website']]);
const systemPreviousOverview=overview;
overview=function(){let f=financeNumbers(),due=db.renewals.filter(r=>r.status==='planned'&&renewalReminderDate(r)<=new Date().toISOString().slice(0,10)&&scopedLeads().some(l=>l.id===r.clientId));return systemPreviousOverview()+`<section class="card"><div class="sectionhead"><h2>finance / ${E(db.financialSettings.period)}</h2>${button('open finance','finance','secondary')}</div><p>${money(f.received)} verified receipts · ${money(f.gap)} to target</p><progress max="${Number(db.financialSettings.target)||1}" value="${f.received}"></progress></section><section class="card" style="margin-top:20px"><h2>renewal reminders due for review</h2>${due.map(r=>`<div class="row"><span>${E(r.title)} · ${E(r.date)}</span>${button('open client','lead/'+r.clientId+'/renewals','secondary mini')}</div>`).join('')||'<p>no reminder reviews due.</p>'}</section>`};
const systemPreviousRender=render;
render=function(){route=location.hash.slice(1).split('/');let views={finance:financeView,staff:staffView,work:taskView,offers:offersView,system:systemStatus};if(views[route[0]]){root.innerHTML=demo()+workspace(views[route[0]]());attachLabels();drawChat()}else systemPreviousRender()};

function createStaffProfile(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));db.staff.push({...d,id:uid('staff'),target:Number(d.target),achieved:0,salary:0,salaryStatus:'not paid',commission:0,commissionStatus:'pending approval',review:''});save();render();toast('staff profile saved')}
const systemPreviousClientView=clientView;
clientView=function(){let l=lead(route[1]);if(l&&route[2]==='proposal'&&l.proposalVersion?.understood){let p=l.proposalVersion;return flowHeader(l,'proposal')+flowTitle('awareness / a reviewed recommendation','your next step.','a concise recommendation based on the answers you shared.')+`<article class="proposal-preview"><p>${E(p.understood)}</p><h3>your first priority</h3><p>${E(p.priority)}</p><p>${E(p.recommendation)}</p><div class="flow-next"><span>your next action</span><strong>${E(p.next)}</strong></div></article><div class="flow-actions">${l.roadmapVersion?button('open my roadmap →','client/'+l.id+'/roadmap'):note('your roadmap is being prepared. your team will update this journey when it is ready.')}</div>`+flowEnd(l)}return systemPreviousClientView()};
const systemPublishRoadmap=publishRoadmapFor;
publishRoadmapFor=function(id){let l=lead(id),missing=db.services.filter(s=>l.selected.includes(s.id)).flatMap(s=>(s.dependencies||[]).filter(d=>!l.selected.includes(d)));if(missing.length){toast('include prerequisite items in the roadmap too: '+[...new Set(missing)].join(', '));return}systemPublishRoadmap(id)};

render();
